#!/usr/bin/env python3
"""Generate the dependency-free static website from public content only."""
from pathlib import Path
from html import escape as e
import hashlib, json, re
from datetime import date
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'content/site.json').read_text())
BASE=D['url']; pubs=D['publications']
CV_URL='/assets/Shaoyang_Zhang_CV.pdf?v='+hashlib.sha256((ROOT/'assets/Shaoyang_Zhang_CV.pdf').read_bytes()).hexdigest()[:12]
NOTES=[('who-should-own-the-ai-interface','Who should own the AI interface?','Personal agents, service APIs, and the distance between intent and interface.','Agents & interfaces'),('artificial-minds-and-possibility','Artificial minds and the possibility of consciousness','Why being engineered should not settle the question of having a mind.','Cognition & philosophy')]
NOTES += [('memory-as-compression-and-reconstruction','Agent memory as compression and reconstruction','Gist-preserving memory and reconstruction conditioned on later experiences.','Agents & memory'),('miku-and-my-research-interests','Miku and the questions that brought me to AI','Cultural motivation, emotional intelligence, and the tension between building and immersion.','Motivation & cognition')]
NOTE_META=json.loads((ROOT/'content/note-dates.json').read_text())
NOTES.sort(key=lambda n:NOTE_META[n[0]]['discussed'],reverse=True)
def note_date(slug):return date.fromisoformat(NOTE_META[slug]['discussed']).strftime('%d %b %Y')
pages=[]
def write(path,content):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
def shell(title,content,section='',path='/',description=None):
 desc=description or 'Shaoyang Zhang · CS at the University of Michigan. Research in model mechanisms, world-model safety, and human–AI interaction.'
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if section==label else '')+f'>{label}</a>' for label,url in [('Home','/'),('Research','/research/'),('Work','/publications/'),('Projects','/projects/'),('Notes','/notes/'),('About','/about/')])
 meta_title=('Shaoyang Zhang · Research & Notes' if title=='Home' else title+' · Shaoyang Zhang')
 schema={'@context':'https://schema.org','@type':'Person','name':D['name'],'alternateName':[D['chinese_name'],D['nickname']],'url':BASE,'email':'mailto:'+D['email'],'sameAs':[D['github'],D['linkedin']],'affiliation':{'@type':'CollegeOrUniversity','name':'University of Michigan'},'knowsAbout':['Mechanistic interpretability','World-model safety','Human–AI interaction']}
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(meta_title)}</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#f8f7f3"><link rel="canonical" href="{BASE}{path}"><meta property="og:title" content="{e(meta_title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE}{path}"><meta property="og:image" content="{BASE}/assets/social-card.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="wordmark" href="/" aria-label="Shaoyang Zhang, home"><span class="monogram" aria-hidden="true">sz</span>Shaoyang Zhang</a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false">Menu</button><nav id="main-nav" aria-label="Main navigation">{nav}<a class="cv-link" href="/cv/">CV ↗</a></nav></div></header><main id="main" class="wrap">{content}</main><footer class="wrap footer"><span>© 2026 Shaoyang Zhang <span aria-hidden="true">·</span> Made with curiosity.</span><div class="footer-links"><a href="mailto:{D['email']}">Email</a><a href="{D['github']}">GitHub ↗</a><a href="{D['linkedin']}">LinkedIn ↗</a><a href="/cv/">CV</a></div></footer></body></html>'''
def page(path,title,content,section='',description=None):
 write(('index.html' if path=='/' else path.strip('/')+'/index.html'),shell(title,content,section,path,description));pages.append(path)
def head(kicker,title,desc=''):
 return f'<div class="page-head"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></div>'
def sect(n,title,link='',label=''):
 return f'<div class="section-top"><div><span class="section-number">{n}</span><h2>{title}</h2></div>'+ (f'<a class="text-link" href="{link}">{label} ↗</a>' if link else '')+'</div>'
def authors(s):return e(s).replace('Shaoyang Zhang','<strong>Shaoyang Zhang</strong>')
def pub(p,full=False):
 links=''.join(f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{label} ↗</a>' for label,url in p['links'].items())
 citation=f'<details><summary>View citation</summary><pre class="bib-code" id="bib-{p["id"]}">{e(p["bibtex"])}</pre></details>' if full else ''
 extra=f'<div class="contribution"><b>My contribution</b>{p["contribution"]}</div>' if full else ''
 copy=f'<button data-copy-citation="bib-{p["id"]}" aria-label="Copy BibTeX for {e(p["short"])}">Copy BibTeX</button>' if full else ''
 figure = f'<div class="pub-visual"><img src="/assets/{p["id"]}.svg" alt="{e(p["category"])} conceptual illustration" loading="lazy" width="260" height="190"></div>'
 if p['id'] in ('oasis','knowsim'):
  alt = 'Standard AttnResidual compared with OASIS' if p['id']=='oasis' else 'Knowledge-state evolution for users with different prior knowledge'
  src = f'/assets/papers/{p["id"]}-figure1.png'
  figure = f'<figure class="paper-figure"><a class="pub-visual" href="{src}" target="_blank" rel="noopener" aria-label="Open {p["short"]} Figure 1 at full size"><img src="{src}" alt="{alt}" loading="lazy"></a><figcaption><a href="{next(iter(p["links"].values()))}">{p["short"]}, Figure 1</a> · <a href="{src}" target="_blank" rel="noopener">Enlarge ↗</a></figcaption></figure>'
 return f'''<article class="pub-row" id="{p['id']}" data-paper data-year="{p['year']}">{figure}<div><div class="pub-meta"><span class="venue">{p['venue']}</span><span>· {p['extra']}</span></div><h3><a href="{next(iter(p['links'].values()))}">{p['title']}</a></h3><p class="authors">{authors(p['authors'])}</p><p class="summary">{p['summary']}</p>{extra}<div class="pub-links">{links}{copy}</div>{citation}</div></article>'''
def notes_list():
 return '<div class="notes-list">'+''.join(f'<a class="note-row" href="/notes/{slug}/"><time datetime="{NOTE_META[slug]["discussed"]}"><span class="date-label">First discussed</span>{note_date(slug)}</time><div><h3>{title}</h3><p>{desc}</p></div><span class="arrow" aria-hidden="true">↗</span></a>' for slug,title,desc,topic in NOTES)+'</div>'
research_grid='''<div class="research-grid"><div class="research-item"><span class="index">01 / MECHANISMS</span><h3>What happens<br>inside the model?</h3><p>I study attention, activation structure, and internal representations to understand how model behavior arises.</p></div><div class="research-item"><span class="index">02 / RELIABILITY</span><h3>Can we trust<br>what it predicts?</h3><p>I study world-model hijacking and targeted adversarial threats to model behavior.</p></div><div class="research-item"><span class="index">03 / PEOPLE</span><h3>Does it understand<br>the person?</h3><p>I build and study user simulation systems that account for evolving knowledge and multi-turn interaction.</p></div></div>'''
current='''<article class="pub-row" id="current-research" data-paper data-year="ongoing"><figure class="paper-figure"><a class="pub-visual" href="/research/world-model-reliability/" aria-label="World-model hijacking problem overview"><img src="/assets/world-model-hijacking.svg" alt="Normal and attacked pipelines: input image, imagined video, and downstream IDM action" loading="lazy"></a><figcaption>Conceptual problem overview</figcaption></figure><div><div class="pub-meta"><span class="venue">Ongoing</span><span>· Project lead · World-model safety</span></div><h3><a href="/research/world-model-reliability/">Targeted attacks on world models</a></h3><p class="summary">I lead research on world-model hijacking: targeted adversarial attacks that aim to steer model behavior toward an attacker-chosen objective.</p><p class="quiet">Methods and results will accompany a public release.</p><div class="pub-links"><a href="/research/world-model-reliability/">Research overview &amp; my role ↗</a></div></div></article>'''

timeline='''<div class="timeline-row"><div class="dates">Mar 2026 — Present</div><div><h3>Northwestern University</h3><p class="role">Undergraduate Research Assistant · Remote</p><p>Leading ongoing research on world-model hijacking and targeted adversarial attacks and contributing to mechanistic interpretability work on attention sinks and activation outliers.</p></div></div><div class="timeline-row"><div class="dates">Oct 2025 — Sep 2026</div><div><h3>Michigan Institute for Data and AI in Society</h3><p class="role">Undergraduate Research Assistant · University of Michigan</p><p>Worked with Prof. Q. Vera Liao and Dr. Yoonjoo Lee on knowledge-state-aware user simulation and multi-turn information-seeking interactions. Built experimental pipelines and the initial human validation-study system for KnowSim.</p></div></div><div class="timeline-row"><div class="dates">Oct 2024 — Oct 2025</div><div><h3>Data-informed Design and Intelligent Systems Laboratory</h3><p class="role">Undergraduate Research Assistant · Shanghai Jiao Tong University</p><p>Worked with Prof. Youyi Bi and Dr. Chang Liu on imitation learning for robotic manipulation. Reproduced MimicPlay and developed keyboard-based robotic-arm teleoperation for collecting demonstration trajectories.</p></div></div>'''
education='''<div class="timeline-row"><div class="dates">Aug 2025 — May 2027<br>Expected graduation</div><div><h3>University of Michigan, Ann Arbor</h3><p class="role">B.S.E. in Computer Science</p><p>Cheng Family Scholarship (2025); Dean’s List.</p></div></div><div class="timeline-row"><div class="dates">Aug 2023 — Aug 2027<br>Expected graduation</div><div><h3>Shanghai Jiao Tong University</h3><p class="role">B.E. in Mechanical Engineering</p><p>Academic Excellence Scholarship (2024). President of the ASME UMJI Student Chapter and Vice President of the Students Science &amp; Technology Innovation Association.</p></div></div>'''
projects='''<div class="project-list"><article class="project-block"><span class="tag">Robotics · Research engineering</span><h3>Learning from demonstrations</h3><p>A keyboard-based teleoperation framework for robotic arms, built to collect human demonstrations for imitation learning. This work grew out of reproducing and studying long-horizon manipulation with MimicPlay.</p><a class="text-link" href="https://github.com/j96w/MimicPlay">MimicPlay reference implementation ↗</a></article><article class="project-block"><span class="tag">Course project · In development</span><h3>DATA TAMER</h3><p>A team project for EECS 448 exploring StarCraft II win-probability prediction and attribution. The planned approach combines spatial sequences and structured game-state features to study which aspects of a state influence the predicted outcome.</p><p class="quiet">Current focus: data reconstruction, predictive modeling, and interpretable evaluation.</p></article></div>'''
photo='''<div class="portrait-side"><div class="portrait-frame"><img src="/assets/portrait.png" alt="Shaoyang Zhang" width="284" height="284" fetchpriority="high"></div><div><p class="portrait-caption"><span class="dot"></span> Ann Arbor, Michigan</p><p class="opportunity">Exploring PhD opportunities<br><strong>Fall 2027</strong></p></div></div>'''
home=f'''<section class="hero"><div><span class="eyebrow">Machine learning · Cognition · Human–AI interaction</span><h1>Shaoyang Zhang<span style="color:var(--accent)">.</span></h1><div class="name-line"><span class="chinese" lang="zh">张劭扬</span><span>Also known as Onion Green</span></div><p class="intro">I study how AI systems work, how they fail, and how they can better understand the people they serve.</p><p class="bio">I’m a computer science undergraduate at the <a class="inline-link" href="https://umich.edu/">University of Michigan</a>, with a background in mechanical engineering at Shanghai Jiao Tong University. My research connects model mechanisms, world-model safety, and human–AI interaction.</p><div class="hero-links"><a href="mailto:{D['email']}">Email ↗</a><a href="{D['github']}">GitHub ↗</a><a href="{D['linkedin']}">LinkedIn ↗</a><a href="{CV_URL}">CV ↓</a></div></div>{photo}</section><aside class="news" aria-label="Recent news"><span class="news-label">Recently</span><div class="news-items"><div class="news-row"><time datetime="2026-09">Sep 2026</time><span><a class="inline-link" href="/publications/#oasis">OASIS</a> accepted to <strong>NeurIPS 2026</strong>; COLM Efficient Reasoning Workshop Spotlight.</span></div><div class="news-row"><time datetime="2026-08">Aug 2026</time><span><a class="inline-link" href="/publications/#knowsim">KnowSim</a> accepted to the <strong>EMNLP 2026 Main Conference</strong>.</span></div></div></aside><section class="section">{sect('01 / SELECTED WORK','Research & publications','/publications/','All work')}<div>{current}{pub(pubs[0])}{pub(pubs[1])}</div></section><section class="section">{sect('02 / RESEARCH','From mechanisms to people','/research/','Research & projects')}{research_grid}</section><section class="section">{sect('03 / NOTEBOOK','Questions I’m thinking about','/notes/','All notes')}{notes_list()}</section><section class="section about-strip"><div><span class="section-number">04 / A LITTLE MORE</span><h2>Engineering, with<br>a human question.</h2></div><div><p>My path has moved from mechanical engineering and robotics to language models and human–AI interaction. I’m drawn to problems where understanding a system’s internal mechanisms changes how we evaluate and use it.</p><p>Beyond research, I follow Vocaloid music, especially Hatsune Miku. The connection between technology, expression, and human meaning is a lasting source of curiosity.</p><a class="text-link" href="/about/">More about me ↗</a></div></section>'''
page('/','Home',home,'Home')
page('/research/','Research',head('Research & projects','Mechanisms. Behavior. People.','I connect the study of internal model representations with questions about reliability and human understanding.')+f'<div class="page-body"><section class="section">{research_grid}</section><section class="section">{sect("01 / EXPERIENCE","Where I’ve worked")}{timeline}</section><section class="section" id="projects">{sect("02 / BUILDING","Selected projects","/projects/","Explore projects")}{projects}</section><section class="section"><h2>Selected work</h2><p class="section-intro">Ongoing research and published work, side by side.</p>{current}{pub(pubs[0])}{pub(pubs[1])}</section></div>','Research')
page('/projects/','Projects',head('Research engineering','Ideas into systems.','Selected systems I have built or helped develop, spanning model evaluation, user simulation, and robotics.')+f'<div class="page-body"><section class="section">{sect("01 / SYSTEMS","Research infrastructure")}<div class="project-list"><article class="project-block"><span class="tag">Ongoing · Project lead</span><h3>Targeted attacks on world models</h3><p>I lead research on world-model hijacking: targeted adversarial attacks that aim to steer model behavior toward an attacker-chosen objective.</p><a class="text-link" href="/research/world-model-reliability/">Research overview &amp; my role ↗</a></article><article class="project-block"><span class="tag">KnowSim · EMNLP 2026</span><h3>Simulating users who learn</h3><p>I built and revised the experimental pipeline for knowledge-state-aware user simulation: information-unit extraction, knowledge updates, query generation, and evaluation. I also implemented the initial human validation-study system.</p><a class="text-link" href="/publications/#knowsim">Paper &amp; contribution ↗</a></article><article class="project-block"><span class="tag">OASIS · NeurIPS 2026</span><h3>Inspecting model mechanisms</h3><p>I contributed controlled interventions and layer-wise representation analysis to investigate attention sinks and activation outliers. This work connects internal model behavior with inference stability and robustness.</p><a class="text-link" href="/publications/#oasis">Paper &amp; contribution ↗</a></article></div></section><section class="section">{sect("02 / BUILDING","Robotics & game analysis")}{projects}</section></div>','Projects')
page('/research/world-model-reliability/','Targeted attacks on world models',head('Ongoing research · Project lead','Targeted attacks<br>on world models.','World-model hijacking and adversarially directed behavior.')+'''<div class="page-body"><a class="text-link" href="/research/">← All research</a><figure class="wm-header"><a href="/assets/world-model-hijacking.svg" target="_blank" rel="noopener"><img src="/assets/world-model-hijacking.svg" width="1440" height="560" alt="Normal versus attacked pipeline: a perturbed input image leads to a hijacked imagined video and redirected IDM actions."></a><figcaption>Problem scope: attacked image → hijacked imagination → redirected action. Conceptual illustration, not experimental evidence. <a href="/assets/world-model-hijacking.svg" target="_blank" rel="noopener">View full size ↗</a></figcaption></figure><section class="section research-story"><div><span class="eyebrow">Research direction</span><h2>When behavior is<br>deliberately redirected.</h2></div><div><p>I lead research on world-model hijacking: targeted adversarial attacks that aim to steer model behavior toward an attacker-chosen objective.</p><p>The central question concerns intentional, directed manipulation of model behavior.</p></div></section><section class="section research-story"><div><span class="eyebrow">My role</span><h2>Project leadership.</h2></div><div><p>I lead the research and contribute to its implementation and evaluation.</p></div></section><section class="section research-story"><div><span class="eyebrow">Status</span><h2>Work in progress.</h2></div><div><p>This overview is limited to the broad research direction and my role. Technical details and research artifacts are not available here.</p><p>The diagram illustrates the problem scope. It does not disclose the attack construction or report experimental outcomes.</p></div></section></div>''','Research')
