page('/publications/','Work',head('Research portfolio','Research & publications','Ongoing investigations and published papers, with my role in each.')+f'<div class="page-body">{filters}<div>'+current+''.join(pub(p,True) for p in pubs)+'</div><p id="no-results" class="empty" hidden>No work matches this search. Try another term or select All.</p><p class="quiet">* Equal contribution. Publication links point to public versions.</p></div>','Work')
page('/notes/','Notes',head('Research notebook','Notes & open questions','Working ideas about agents, cognition, and the relationship between engineered systems and human experience.')+f'<div class="page-body">{notes_list()}<p class="quiet" style="margin-top:28px">Dates identify the earliest located source discussions, rather than website publication. Each essay separately records when it was reconstructed and edited. These are working ideas and personal perspectives, rather than empirical findings.</p></div>','Notes')
def md(text):
 out=[]
 for b in text.strip().split('\n\n'):
  if b.startswith('# '):continue
  if b.startswith('## '):out.append('<h2>'+e(b[3:])+'</h2>')
  else:out.append('<p>'+e(b.replace('\n',' '))+'</p>')
 return '\n'.join(out)
for slug,title,desc,topic in NOTES:
 body=f'<header class="article-head"><a class="text-link" href="/notes/">← Back to notes</a><h1>{title}</h1><p class="article-meta">{topic} · Working note<br>First discussed <time datetime="{NOTE_META[slug]["discussed"]}">{note_date(slug)}</time> · Reconstructed &amp; edited <time datetime="{NOTE_META[slug]["edited"]}">29 October 2026</time></p></header><article class="prose">'+md((ROOT/f'content/notes/{slug}.md').read_text())+'</article><div class="article-end"><p class="quiet">'+e(NOTE_META[slug]['provenance'])+'</p><a class="text-link" href="mailto:'+D['email']+'">Continue the conversation ↗</a></div>'
 page('/notes/'+slug+'/',title,body,'Notes',desc)
about=f'''{head('About me','Curiosity across disciplines.','I’m Shaoyang (张劭扬), a computer science undergraduate in Ann Arbor. You may also know me online as Onion Green.')}<div class="page-body"><div class="about-strip"><div><p>I study computer science at the University of Michigan and mechanical engineering at Shanghai Jiao Tong University. My research interests sit at the intersection of model interpretability, AI safety, and human–AI interaction.</p><p>Work on user simulation made me interested in the relationship between a model’s response and a person’s evolving understanding. Work on attention and world models has brought me closer to the mechanisms that produce behavior. I want to connect these perspectives.</p><p>I am exploring PhD opportunities beginning in Fall 2027, particularly around model mechanisms, robust agents, and cognition-aware AI.</p></div><div><span class="eyebrow">Beyond the lab</span><p>I am a long-time Vocaloid listener and a fan of <a class="miku-door" href="/39/" aria-label="Hatsune Miku — my concert journal">Hatsune Miku</a>. Music and live performances are a reminder of how technical systems can become mediums for creativity and shared experience.</p><p>I keep this site as both an academic home and a notebook: a place for finished work, ongoing questions, and the ideas that connect them.</p><a class="text-link" href="/notes/">Visit the notebook ↗</a></div></div><section class="section">{sect('01 / EDUCATION','Two engineering perspectives')}{education}</section><section class="section"><h2>Let’s talk.</h2><p class="section-intro">For research conversations and opportunities, email is the best place to reach me.</p><div class="contact-panel"><a href="mailto:{D['email']}">{D['email']} ↗</a></div></section></div>'''
page('/about/','About',about,'About')
